export interface GridCell {
  row: number
  col: number
}

export interface GridSize {
  rows: number
  cols: number
}

export interface GridKey {
  key: string
  ctrlKey?: boolean
  metaKey?: boolean
  altKey?: boolean
  shiftKey?: boolean
}

const ARROWS: Record<string, [number, number]> = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }

/** The cell a navigation key moves focus to, or null when the key does not move. */
export function gridMove(e: GridKey, at: GridCell, size: GridSize): GridCell | null {
  const to = target(e, at, size)
  return to && inside(to, size) && (to.row !== at.row || to.col !== at.col) ? to : null
}

function target(e: GridKey, at: GridCell, size: GridSize): GridCell | null {
  if (e.altKey || e.shiftKey || e.metaKey) return null
  const arrow = ARROWS[e.key]
  if (arrow && e.ctrlKey) return null
  if (arrow) return { row: at.row + arrow[0], col: at.col + arrow[1] }
  const toGridCorner = !!e.ctrlKey
  if (e.key === 'Home') return { row: toGridCorner ? 0 : at.row, col: 0 }
  if (e.key === 'End') return { row: toGridCorner ? size.rows - 1 : at.row, col: size.cols - 1 }
  return null
}

const inside = (c: GridCell, size: GridSize) => c.row >= 0 && c.col >= 0 && c.row < size.rows && c.col < size.cols

/** The nearest cell inside the grid (the remembered active cell after the grid shrank). */
export const clampCell = (c: GridCell, size: GridSize): GridCell => ({
  row: Math.max(0, Math.min(c.row, size.rows - 1)),
  col: Math.max(0, Math.min(c.col, size.cols - 1)),
})
